<script>
(() => {
 const methodFilter=document.getElementById('order-payment-method-filter'),paymentStatusFilter=document.getElementById('order-payment-status-filter');
 const rows=[...document.querySelectorAll('[data-order-row]')];
 function filterPayments(){const method=(methodFilter?.value||'').toLocaleLowerCase(),status=(paymentStatusFilter?.value||'').toUpperCase();let visible=0;rows.forEach(row=>{const methodMatch=!method||row.dataset.paymentMethod===method;const statusMatch=!status||row.dataset.paymentStatus===status;row.hidden=!(methodMatch&&statusMatch);if(!row.hidden)visible++});const empty=document.getElementById('orders-no-filter-results');if(empty)empty.hidden=rows.length===0||visible>0}
 methodFilter?.addEventListener('change',filterPayments);paymentStatusFilter?.addEventListener('change',filterPayments);
 const cancelDialog=document.getElementById('cancel-order-confirmation');let cancelForm=null;
 document.querySelectorAll('[data-order-transition-form]').forEach(form=>form.addEventListener('submit',event=>{if(form.dataset.nextStatus!=='CANCELLED')return;event.preventDefault();cancelForm=form;cancelDialog.showModal()}));
 document.getElementById('dismiss-cancel-order')?.addEventListener('click',()=>cancelDialog.close());
 document.getElementById('confirm-cancel-order')?.addEventListener('click',()=>{if(!cancelForm)return;cancelDialog.close();cancelForm.submit()});
})();
</script>
</body>
